import hsk1 from "./hsk1.json";
import hsk2 from "./hsk2.json";
import hsk3 from "./hsk3.json";
import hsk4 from "./hsk4.json";

// Available level datasets (generated by scripts/convert.py).
const datasets = { 1: hsk1, 2: hsk2, 3: hsk3, 4: hsk4 };

function countWords(level) {
  return level.lessons.reduce((n, l) => n + l.words.length, 0);
}

// Level metadata for the home screen. HSK 4/5 are placeholders until data arrives.
export const levels = [1, 2, 3, 4, 5].map((lv) => {
  const ds = datasets[lv];
  return {
    level: lv,
    available: !!ds,
    lessonCount: ds ? ds.lessons.length : 0,
    wordCount: ds ? countWords(ds) : 0,
  };
});

export function getLevel(level) {
  return datasets[Number(level)] || null;
}

export function getLesson(level, lessonNum) {
  const ds = getLevel(level);
  if (!ds) return null;
  return ds.lessons.find((l) => l.num === Number(lessonNum)) || null;
}

export function allWords(level) {
  const ds = getLevel(level);
  if (!ds) return [];
  return ds.lessons.flatMap((l) => l.words);
}
